# GR4ML as code: business goal -> decision -> question -> insight, with indicators that can be checked
from dataclasses import dataclass, field

@dataclass
class Indicator:
    name: str; target: float; current: float; lower_is_better: bool = True
    def status(self):
        ok = self.current <= self.target if self.lower_is_better else self.current >= self.target
        near = abs(self.current - self.target) / self.target < 0.10
        return "green" if ok else ("amber" if near else "red")

@dataclass
class Insight:
    name: str; type: str; input: str; output: str; usage: str; update: str; learning_period: str

@dataclass
class Goal:
    name: str; kind: str; children: list = field(default_factory=list)
    indicators: list = field(default_factory=list); answered_by: Insight = None
    def show(self, depth=0):
        pad = "  " * depth
        print(f"{pad}{self.kind}: {self.name}")
        for i in self.indicators: print(f"{pad}  indicator {i.name}: {i.current} vs target {i.target} -> {i.status()}")
        if self.answered_by: print(f"{pad}  answered by insight '{self.answered_by.name}' ({self.answered_by.output}, updated {self.answered_by.update})")
        for c in self.children: c.show(depth + 1)

insight = Insight("Credit risk predictive model", "predictive model", "applicant profile", "credit risk High/Low", "per instance", "monthly", "last 48 months")
question = Goal("What will be the credit risk of the application at hand?", "Question goal", answered_by=insight)
decision = Goal("Decision on credit application", "Decision goal", children=[question])
strategic = Goal("Process applications", "Strategic goal", children=[decision],
                 indicators=[Indicator("average resolution time (days)", target=2.0, current=3.1)])
print("Actor 'Case workers' desires:")
strategic.show(1)
# What happens to the indicator if the model automates 60% of low-risk decisions (illustrative)
auto_share, manual_days, auto_days = 0.6, 3.1, 0.2
strategic.indicators[0].current = round(auto_share * auto_days + (1 - auto_share) * manual_days, 2)
print("\nafter automating 60% of decisions:", strategic.indicators[0].current, "days ->", strategic.indicators[0].status())
